{"command":"python3 -c "
import os, subprocess, tempfile, shutil

tmpdir = tempfile.mkdtemp()
test_files = [
    '.git', '.gitignore', '.env', '.hidden', '..', '.',
    'README', 'README.md', 'README.txt', 'LICENSE', 'LICENCE', 'COPYING',
    'Cargo.toml', 'package.json', 'Makefile', 'Dockerfile', 'CMakeLists.txt',
    'main.rs', 'index.js', 'app.py', 'test.txt', 'file.tmp', 'a.out',
    'CHANGELOG.md', 'CONTRIBUTING.md', 'SECURITY.md', 'CODE_OF_CONDUCT.md'
]

for f in test_files:
    if f not in ['.', '..']:
        open(os.path.join(tmpdir, f), 'w').close()

def get_imp(filename):
    # find highest imp level where file is included
    highest = -99
    for imp in range(-2, 6):
        res = subprocess.run(['./executable', '-I', str(imp), '-o', filename, tmpdir], capture_output=True, text=True)
        if filename in res.stdout:
            highest = imp
    return highest

for f in test_files:
    print(f'{f}: max_imp = {get_imp(f)}')

shutil.rmtree(tmpdir)
""}

