{"command":"python3 -c "
import os, subprocess, tempfile, shutil

tmpdir = tempfile.mkdtemp()
lockfiles = [
    'Cargo.lock', 'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml',
    'Pipfile.lock', 'poetry.lock', 'Gemfile.lock', 'composer.lock',
    'flake.lock', 'mix.lock'
]

for f in lockfiles:
    open(os.path.join(tmpdir, f), 'w').close()

def get_imp(filename):
    for imp in range(-2, 5):
        res = subprocess.run(['./executable', f'--imp={imp}', '-o', filename, tmpdir], capture_output=True, text=True)
        if filename in res.stdout:
            res2 = subprocess.run(['./executable', f'--imp={imp+1}', '-o', filename, tmpdir], capture_output=True, text=True)
            if filename not in res2.stdout:
                return imp
    return None

for f in lockfiles:
    print(f'{f:20s}: {get_imp(f)}')

shutil.rmtree(tmpdir)
""}

