import os

cat_rs = '''
use std::ffi::CStr;
use std::os::raw::{c_int, c_char};

#[repr(C)]
struct Passwd {
    pw_name: *mut c_char,
    pw_passwd: *mut c_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *mut c_char,
    pw_dir: *mut c_char,
    pw_shell: *mut c_char,
}

extern \"C\" {
    fn getpwuid_r(
        uid: u32,
        pwd: *mut Passwd,
        buf: *mut c_char,
        buflen: usize,
        result: *mut *mut Passwd,
    ) -> c_int;
}

fn main() {
    let mut pwd: Passwd = unsafe { std::mem::zeroed() };
    let mut buf = vec![0i8; 1024];
    let mut result = std::ptr::null_mut();
    unsafe {
        getpwuid_r(1000, &mut pwd, buf.as_mut_ptr(), buf.len(), &mut result);
        if !result.is_null() {
            let name = CStr::from_ptr(pwd.pw_name).to_string_lossy();
            println!(\"User 1000: {}\", name);
        }
    }
}
'''
with open('/tmp/test_libc.rs', 'w') as f:
    f.write(cat_rs)
" && rustc /tmp/test_libc.rs -o /tmp/test_libc && /tmp/test_libc
"}

