extensions = [
    'txt', 'rs', 'py', 'js', 'ts', 'jsx', 'tsx', 'json', 'toml', 'yaml', 'yml', 'xml', 'html', 'css', 'scss',
    'c', 'cpp', 'h', 'hpp', 'go', 'sh', 'bash', 'zsh', 'fish', 'md', 'pdf', 'zip', 'tar', 'gz', 'bz2', 'xz', '7z',
