    'o', 'a', 'dylib', 'dll', 'class', 'java', 'kt', 'swift', 'rb', 'php', 'pl', 'lua', 'hs', 'ex', 'exs', 'erl',
    'clj', 'elm', 'scala', 'dart', 'r', 'vim', 'lock', 'log', 'env', 'conf', 'ini', 'cfg', 'sql', 'db', 'sqlite'
]

filenames = [
    'README', 'README.md', 'README.txt', 'LICENSE', 'LICENCE', 'COPYING', 'Cargo.toml', 'Cargo.lock',
    'package.json', 'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'Dockerfile', 'docker-compose.yml',
    'Makefile', 'CMakeLists.txt', '.gitignore', '.gitattributes', '.env', '.DS_Store'
]

tmpdir = tempfile.mkdtemp()
for ext in extensions:
    open(os.path.join(tmpdir, f'test.{ext}'), 'w').close()
for f in filenames:
    if f not in os.listdir(tmpdir):
        open(os.path.join(tmpdir, f), 'w').close()

res = subprocess.run(['./executable', '-a', 'false', tmpdir], capture_output=True, text=True)
icon_map = {}
for line in res.stdout.strip().split('\n'):
    if not line.strip(): continue
    parts = line.split()
    if len(parts) >= 2:
        # Check first char or unicode
        first_token = parts[0]
        # if first token is icon
        if ord(first_token[0]) > 256:
            icon_map[parts[-1]] = hex(ord(first_token[0]))
        else:
            icon_map[parts[-1]] = None

for k, v in sorted(icon_map.items()):
    print(f'{k:25s}: {v}')

shutil.rmtree(tmpdir)
""}

