// Regex engine for -e / -o
#[derive(Debug, Clone)]
enum RegexAST {
    Literal(char),
    Any,
    StartAnchor,
    EndAnchor,
    Class(Vec<(char, char)>, bool), // ranges, inverted
    Star(Box<RegexAST>),
