struct RegexParser<'a> {
    chars: Vec<char>,
    pos: usize,
    raw: &'a str,
}

impl<'a> RegexParser<'a> {
    fn new(raw: &'a str) -> Self {
        RegexParser {
            chars: raw.chars().collect(),
            pos: 0,
            raw,
        }
    }

    fn parse(&mut self) -> Result<RegexAST, String> {
        let ast = self.parse_alt()?;
        if self.pos < self.chars.len() {
            return Err(format!("unexpected character at pos {}", self.pos));
        }
        Ok(ast)
    }

    fn parse_alt(&mut self) -> Result<RegexAST, String> {
        let mut alts = vec![self.parse_concat()?];
        while self.pos < self.chars.len() && self.chars[self.pos] == '|' {
            self.pos += 1;
            alts.push(self.parse_concat()?);
        }
        if alts.len() == 1 {
            Ok(alts.remove(0))
        } else {
            Ok(RegexAST::Alt(alts))
        }
    }

    fn parse_concat(&mut self) -> Result<RegexAST, String> {
        let mut vec = Vec::new();
        while self.pos < self.chars.len() {
            let ch = self.chars[self.pos];
            if ch == '|' || ch == ')' {
                break;
            }
            vec.push(self.parse_quantifier()?);
        }
        if vec.len() == 1 {
            Ok(vec.remove(0))
        } else {
            Ok(RegexAST::Concat(vec))
        }
    }

    fn parse_quantifier(&mut self) -> Result<RegexAST, String> {
        let atom = self.parse_atom()?;
        if self.pos < self.chars.len() {
            match self.chars[self.pos] {
                '*' => { self.pos += 1; Ok(RegexAST::Star(Box::new(atom))) }
                '+' => { self.pos += 1; Ok(RegexAST::Plus(Box::new(atom))) }
                '?' => { self.pos += 1; Ok(RegexAST::Question(Box::new(atom))) }
                _ => Ok(atom)
            }
        } else {
            Ok(atom)
        }
    }

    fn parse_atom(&mut self) -> Result<RegexAST, String> {
        if self.pos >= self.chars.len() {
            return Err("unexpected end of pattern".to_string());
        }
        let ch = self.chars[self.pos];
        self.pos += 1;
        match ch {
            '^' => Ok(RegexAST::StartAnchor),
            '$' => Ok(RegexAST::EndAnchor),
            '.' => Ok(RegexAST::Any),
            '\\' => {
                if self.pos >= self.chars.len() {
                    return Err("trailing backslash".to_string());
                }
                let escaped = self.chars[self.pos];
                self.pos += 1;
                match escaped {
                    'd' => Ok(RegexAST::Class(vec![('0', '9')], false)),
                    'w' => Ok(RegexAST::Class(vec![('a', 'z'), ('A', 'Z'), ('0', '9'), ('_', '_')], false)),
                    's' => Ok(RegexAST::Class(vec![(' ', ' '), ('\t', '\t'), ('\n', '\n'), ('\r', '\r')], false)),
                    other => Ok(RegexAST::Literal(other)),
                }
            }
            '[' => {
                let inverted = if self.pos < self.chars.len() && self.chars[self.pos] == '^' {
                    self.pos += 1;
                    true
                } else {
                    false
                };
                let mut ranges = Vec::new();
                let mut closed = false;
                while self.pos < self.chars.len() {
                    let c = self.chars[self.pos];
                    self.pos += 1;
                    if c == ']' {
                        closed = true;
                        break;
                    }
                    if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '-' && self.chars[self.pos + 1] != ']' {
                        self.pos += 1; // skip '-'
                        let end_c = self.chars[self.pos];
                        self.pos += 1;
                        ranges.push((c, end_c));
                    } else {
                        ranges.push((c, c));
                    }
                }
                if !closed {
                    return Err("unclosed character class".to_string());
                }
                Ok(RegexAST::Class(ranges, inverted))
            }
            '(' => {
                let ast = self.parse_alt()?;
                if self.pos < self.chars.len() && self.chars[self.pos] == ')' {
                    self.pos += 1;
                    Ok(ast)
                } else {
                    Err("unclosed parenthesis".to_string())
                }
            }
            '*' | '+' | '?' => Err(format!("unexpected quantifier '{}'", ch)),
            other => Ok(RegexAST::Literal(other)),
        }
    }
}

fn main() {
    println!("pls");
}
