    Literal(char),
    Any,
    StartAnchor,
    EndAnchor,
    Class(Vec<(char, char)>, bool), // ranges, inverted
    Star(Box<RegexAST>),
    Plus(Box<RegexAST>),
    Question(Box<RegexAST>),
    Concat(Vec<RegexAST>),
    Alt(Vec<RegexAST>),
}

#[derive(Debug, Clone)]
struct SimpleRegex {
    ast: RegexAST,
    pattern: String,
}

impl SimpleRegex {
    fn new(pattern: &str) -> Result<Self, String> {
        let mut parser = RegexParser::new(pattern);
        let ast = parser.parse()?;
        Ok(SimpleRegex {
            ast,
            pattern: pattern.to_string(),
        })
    }

    fn is_match(&self, text: &str) -> bool {
        // Test matching at all possible start positions unless anchored at start
        let chars: Vec<char> = text.chars().collect();
        if self.has_start_anchor(&self.ast) {
            self.match_ast(&self.ast, &chars, 0).is_some()
        } else {
            for i in 0..=chars.len() {
                if self.match_ast(&self.ast, &chars, i).is_some() {
                    return true;
                }
            }
            false
        }
    }

    fn has_start_anchor(&self, ast: &RegexAST) -> bool {
        match ast {
            RegexAST::StartAnchor => true,
            RegexAST::Concat(vec) => vec.first().map_or(false, |a| self.has_start_anchor(a)),
            _ => false,
        }
    }

    fn match_ast(&self, ast: &RegexAST, text: &[char], idx: usize) -> Option<usize> {
        match ast {
            RegexAST::StartAnchor => {
                if idx == 0 { Some(0) } else { None }
            }
            RegexAST::EndAnchor => {
                if idx == text.len() { Some(0) } else { None }
            }
            RegexAST::Literal(c) => {
                if idx < text.len() && text[idx] == *c {
                    Some(1)
                } else {
                    None
                }
            }
            RegexAST::Any => {
                if idx < text.len() { Some(1) } else { None }
            }
            RegexAST::Class(ranges, inverted) => {
                if idx >= text.len() {
                    return None;
                }
                let ch = text[idx];
                let mut matched = false;
                for &(start, end) in ranges {
                    if ch >= start && ch <= end {
                        matched = true;
                        break;
                    }
                }
                if *inverted {
                    matched = !matched;
                }
                if matched { Some(1) } else { None }
            }
            RegexAST::Concat(vec) => {
                let mut curr = idx;
                for sub in vec {
                    if let Some(consumed) = self.match_ast(sub, text, curr) {
                        curr += consumed;
                    } else {
                        return None;
                    }
                }
                Some(curr - idx)
            }
            RegexAST::Alt(vec) => {
                for sub in vec {
                    if let Some(consumed) = self.match_ast(sub, text, idx) {
                        return Some(consumed);
                    }
                }
                None
            }
            RegexAST::Star(sub) => {
                // Greedy star
                let mut max_matched = 0;
                let mut matches = vec![0];
                let mut curr = idx;
                while curr < text.len() {
                    if let Some(consumed) = self.match_ast(sub, text, curr) {
                        if consumed == 0 { break; }
                        curr += consumed;
                        matches.push(curr - idx);
                    } else {
                        break;
                    }
                }
                matches.pop() // Return largest or backtrack if needed (here return largest)
            }
            RegexAST::Plus(sub) => {
                if let Some(c1) = self.match_ast(sub, text, idx) {
                    if c1 == 0 { return None; }
                    let rest = self.match_ast(&RegexAST::Star(sub.clone()), text, idx + c1);
                    Some(c1 + rest.unwrap_or(0))
                } else {
                    None
                }
            }
            RegexAST::Question(sub) => {
                if let Some(c) = self.match_ast(sub, text, idx) {
                    Some(c)
                } else {
                    Some(0)
                }
            }
        }
    }
}

struct RegexParser<'a> {
    chars: Vec<char>,
    pos: usize,
    raw: &'a str,
}

impl<'a> RegexParser<'a> {
    fn new(raw: &'a str) -> Self {
        RegexParser {
            chars: raw.chars().collect(),
            pos: 0,
            raw,
        }
    }

    fn parse(&mut self) -> Result<RegexAST, String> {
        let ast = self.parse_alt()?;
        if self.pos < self.chars.len() {
            return Err(format!("unexpected character at pos {}", self.pos));
        }
        Ok(ast)
    }

    fn parse_alt(&mut self) -> Result<RegexAST, String> {
        let mut alts = vec![self.parse_concat()?];
        while self.pos < self.chars.len() && self.chars[self.pos] == '|' {
            self.pos += 1;
            alts.push(self.parse_concat()?);
        }
        if alts.len() == 1 {
            Ok(alts.remove(0))
        } else {
            Ok(RegexAST::Alt(alts))
        }
    }

    fn parse_concat(&mut self) -> Result<RegexAST, String> {
        let mut vec = Vec::new();
        while self.pos < self.chars.len() {
            let ch = self.chars[self.pos];
            if ch == '|' || ch == ')' {
                break;
            }
            vec.push(self.parse_quantifier()?);
        }
        if vec.len() == 1 {
            Ok(vec.remove(0))
        } else {
            Ok(RegexAST::Concat(vec))
        }
    }

    fn parse_quantifier(&mut self) -> Result<RegexAST, String> {
        let atom = self.parse_atom()?;
        if self.pos < self.chars.len() {
            match self.chars[self.pos] {
                '*' => { self.pos += 1; Ok(RegexAST::Star(Box::new(atom))) }
                '+' => { self.pos += 1; Ok(RegexAST::Plus(Box::new(atom))) }
                '?' => { self.pos += 1; Ok(RegexAST::Question(Box::new(atom))) }
                _ => Ok(atom)
            }
        } else {
            Ok(atom)
        }
    }

    fn parse_atom(&mut self) -> Result<RegexAST, String> {
        if self.pos >= self.chars.len() {
            return Err("unexpected end of pattern".to_string());
        }
        let ch = self.chars[self.pos];
        self.pos += 1;
        match ch {
            '^' => Ok(RegexAST::StartAnchor),
            '$' => Ok(RegexAST::EndAnchor),
            '.' => Ok(RegexAST::Any),
            '\\' => {
                if self.pos >= self.chars.len() {
                    return Err("trailing backslash".to_string());
                }
                let escaped = self.chars[self.pos];
                self.pos += 1;
                match escaped {
                    'd' => Ok(RegexAST::Class(vec![('0', '9')], false)),
                    'w' => Ok(RegexAST::Class(vec![('a', 'z'), ('A', 'Z'), ('0', '9'), ('_', '_')], false)),
                    's' => Ok(RegexAST::Class(vec![(' ', ' '), ('\t', '\t'), ('\n', '\n'), ('\r', '\r')], false)),
                    other => Ok(RegexAST::Literal(other)),
                }
            }
            '[' => {
                let inverted = if self.pos < self.chars.len() && self.chars[self.pos] == '^' {
                    self.pos += 1;
                    true
                } else {
                    false
                };
                let mut ranges = Vec::new();
                let mut closed = false;
                while self.pos < self.chars.len() {
                    let c = self.chars[self.pos];
                    self.pos += 1;
                    if c == ']' {
                        closed = true;
                        break;
                    }
                    if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '-' && self.chars[self.pos + 1] != ']' {
                        self.pos += 1; // skip '-'
                        let end_c = self.chars[self.pos];
                        self.pos += 1;
                        ranges.push((c, end_c));
                    } else {
                        ranges.push((c, c));
                    }
                }
                if !closed {
                    return Err("unclosed character class".to_string());
                }
                Ok(RegexAST::Class(ranges, inverted))
            }
            '(' => {
                let ast = self.parse_alt()?;
                if self.pos < self.chars.len() && self.chars[self.pos] == ')' {
                    self.pos += 1;
                    Ok(ast)
                } else {
                    Err("unclosed parenthesis".to_string())
                }
            }
            '*' | '+' | '?' => Err(format!("unexpected quantifier '{}'", ch)),
            other => Ok(RegexAST::Literal(other)),
        }
    }
}

