    BlockDevice,
}

impl NodeType {
    fn code(&self) -> char {
        match self {
            NodeType::Directory => 'd',
            NodeType::Fifo => 'p',
            NodeType::File => 'f',
            NodeType::Socket => 's',
            NodeType::Symlink => 'l',
            NodeType::CharDevice => 'c',
            NodeType::BlockDevice => 'b',
        }
    }

    fn cat_rank(&self) -> usize {
        match self {
            NodeType::Directory => 1,
            NodeType::Fifo => 2,
            NodeType::File => 3,
            NodeType::Socket => 4,
            NodeType::Symlink => 5,
            NodeType::CharDevice => 6,
            NodeType::BlockDevice => 7,
        }
    }

    fn suffix(&self) -> &'static str {
        match self {
            NodeType::Directory => "/",
            NodeType::Fifo => "|",
            NodeType::Socket => "=",
            NodeType::Symlink => "@",
            _ => "",
        }
    }

    fn match_filter(&self, f: &str) -> bool {
        match f {
            "dir" => *self == NodeType::Directory,
            "symlink" => *self == NodeType::Symlink,
            "fifo" => *self == NodeType::Fifo,
            "socket" => *self == NodeType::Socket,
            "block-device" => *self == NodeType::BlockDevice,
            "char-device" => *self == NodeType::CharDevice,
