fn parse_bool(val: &str, flag_name: &str) -> Result<bool, String> {
    match val {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => Err(format!(
            "error: invalid value '{}' for '{}\n  [possible values: true, false]\n\nFor more information, try '--help'.",
            val, flag_name
        )),
    }
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let bin_name = args.first().map(|s| s.as_str()).unwrap_or("executable");

    let mut paths = Vec::new();
    let mut details = Vec::new();
    let mut header = true;
    let mut unit = "binary".to_string();
    let mut grid = false;
    let mut down = false;
    let mut icon = true;
    let mut suffix = true;
    let mut sym = true;
    let mut collapse = true;
    let mut align = true;
    let mut types = vec!["all".to_string()];
    let mut imp = 0;
    let mut exclude: Option<SimpleRegex> = None;
    let mut only: Option<SimpleRegex> = None;
    let mut sort_bases = vec!["cat".to_string(), "cname".to_string()];
    let mut custom_sort = false;

    let valid_details = [
        "dev", "ino", "nlink", "typ", "perm", "oct", "user", "uid", "group", "gid",
        "size", "blocks", "btime", "ctime", "mtime", "atime", "git", "none", "std", "all",
    ];
    let valid_units = ["binary", "decimal", "none"];
    let valid_types = [
        "dir", "symlink", "fifo", "socket", "block-device", "char-device", "file", "none", "all",
    ];
    let valid_sorts = [
        "dev", "ino", "nlink", "typ", "cat", "user", "uid", "group", "gid", "size", "blocks",
        "btime", "ctime", "mtime", "atime", "name", "cname", "ext", "inode_", "nlinks_",
        "typ_", "cat_", "user_", "uid_", "group_", "gid_", "size_", "blocks_", "btime_",
        "ctime_", "mtime_", "atime_", "name_", "cname_", "ext_", "none",
    ];

    let mut idx = 1;
    let mut double_dash = false;

    while idx < args.len() {
        let arg = &args[idx];

        if double_dash {
            paths.push(arg.clone());
            idx += 1;
            continue;
        }

        if arg == "--" {
            double_dash = true;
            idx += 1;
            continue;
        }

        if arg == "-h" {
            print_help(bin_name, false);
            process::exit(0);
        } else if arg == "--help" {
            print_help(bin_name, true);
            process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("pls 0.0.1-beta.9");
            process::exit(0);
        } else if arg == "-d" || arg.starts_with("-d=") || arg == "--det" || arg.starts_with("--det=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1.to_string()
            } else {
                idx += 1;
                if idx >= args.len() {
                    eprintln!("error: a value is required for '--det <DETAILS>' but none was supplied\n  [possible values: dev, ino, nlink, typ, perm, oct, user, uid, group, gid, size, blocks, btime, ctime, mtime, atime, git, none, std, all]\n\nFor more information, try '--help'.");
                    process::exit(2);
                }
                args[idx].clone()
            };

            if !valid_details.contains(&val.as_str()) {
                eprintln!("error: invalid value '{}' for '--det <DETAILS>'\n  [possible values: dev, ino, nlink, typ, perm, oct, user, uid, group, gid, size, blocks, btime, ctime, mtime, atime, git, none, std, all]\n\nFor more information, try '--help'.", val);
                process::exit(2);
            }

            if val == "none" {
                details.clear();
            } else if val == "std" {
                for std_det in ["nlink", "typ", "perm", "user", "group", "size", "mtime"] {
                    if !details.contains(&std_det.to_string()) {
                        details.push(std_det.to_string());
                    }
                }
            } else if val == "all" {
                for all_det in [
                    "dev", "ino", "nlink", "typ", "perm", "oct", "user", "uid", "group",
                    "gid", "size", "blocks", "btime", "ctime", "mtime", "atime", "git",
                ] {
                    if !details.contains(&all_det.to_string()) {
                        details.push(all_det.to_string());
                    }
                }
            } else {
                if !details.contains(&val) {
                    details.push(val);
                }
            }
        } else if arg == "-H" || arg.starts_with("-H=") || arg == "--header" || arg.starts_with("--header=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1
            } else {
                idx += 1;
                if idx >= args.len() {
                    eprintln!("error: a value is required for '--header <HEADER>' but none was supplied\n  [possible values: true, false]\n\nFor more information, try '--help'.");
                    process::exit(2);
                }
                &args[idx]
            };
            match parse_bool(val, "--header <HEADER>") {
                Ok(b) => header = b,
                Err(e) => { eprintln!("{}", e); process::exit(2); }
            }
        } else if arg == "-u" || arg.starts_with("-u=") || arg == "--unit" || arg.starts_with("--unit=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1.to_string()
            } else {
                idx += 1;
                if idx >= args.len() {
                    eprintln!("error: a value is required for '--unit <UNIT>' but none was supplied\n  [possible values: binary, decimal, none]\n\nFor more information, try '--help'.");
                    process::exit(2);
                }
                args[idx].clone()
            };
            if !valid_units.contains(&val.as_str()) {
                eprintln!("error: invalid value '{}' for '--unit <UNIT>'\n  [possible values: binary, decimal, none]\n\nFor more information, try '--help'.", val);
                process::exit(2);
            }
            unit = val;
        } else if arg == "-g" || arg.starts_with("-g=") || arg == "--grid" || arg.starts_with("--grid=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1
            } else {
                idx += 1;
                if idx >= args.len() {
                    eprintln!("error: a value is required for '--grid <GRID>' but none was supplied\n  [possible values: true, false]\n\nFor more information, try '--help'.");
                    process::exit(2);
                }
                &args[idx]
            };
            match parse_bool(val, "--grid <GRID>") {
                Ok(b) => grid = b,
                Err(e) => { eprintln!("{}", e); process::exit(2); }
            }
        } else if arg == "-D" || arg.starts_with("-D=") || arg == "--down" || arg.starts_with("--down=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1
            } else {
