                    process::exit(2);
                }
                args[idx].clone()
            };
            match SimpleRegex::new(&val) {
                Ok(r) => exclude = Some(r),
                Err(err_msg) => {
                    eprintln!("error: invalid value '{}' for '--exclude <EXCLUDE>': regex parse error:\n    {}\n    ^\nerror: {}\n\nFor more information, try '--help'.", val, val, err_msg);
