                    eprintln!("error: a value is required for '--sort <SORT_BASES>' but none was supplied\n  [possible values: dev, ino, nlink, typ, cat, user, uid, group, gid, size, blocks, btime, ctime, mtime, atime, name, cname, ext, inode_, nlinks_, typ_, cat_, user_, uid_, group_, gid_, size_, blocks_, btime_, ctime_, mtime_, atime_, name_, cname_, ext_, none]\n\nFor more information, try '--help'.");
                    process::exit(2);
                }
