        } else if arg.starts_with('-') && arg != "-" {
            eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [PATHS]...\n\nFor more information, try '--help'.", arg, arg, arg, bin_name);
            process::exit(2);
        } else {
            paths.push(arg.clone());
        }

        idx += 1;
    }

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    Config {
