fn filter_and_sort_nodes(nodes: &mut Vec<Node>, config: &Config) {
    // 1. Filter by type
    nodes.retain(|n| {
        if config.types.contains(&"none".to_string()) {
            return false;
        }
        if config.types.contains(&"all".to_string()) {
            return true;
        }
        config.types.iter().any(|t| n.node_type.match_filter(t))
    });

    // 2. Filter by importance
    nodes.retain(|n| n.importance >= config.imp);

    // 3. Filter by exclude / only regex
    if let Some(ref ex) = config.exclude {
        nodes.retain(|n| !ex.is_match(&n.name));
    }
    if let Some(ref on) = config.only {
        nodes.retain(|n| on.is_match(&n.name));
    }

    // 4. Collapse Cargo.lock if Cargo.toml exists and config.collapse is true
    if config.collapse {
        let has_cargo_toml = nodes.iter().any(|n| n.name == "Cargo.toml");
        if has_cargo_toml {
            let lock_idx = nodes.iter().position(|n| n.name == "Cargo.lock");
            if let Some(l_idx) = lock_idx {
                let mut lock_node = nodes.remove(l_idx);
                lock_node.icon = get_node_icon(&lock_node.name, lock_node.node_type, true);
                if let Some(toml_node) = nodes.iter_mut().find(|n| n.name == "Cargo.toml") {
                    toml_node.subordinate = Some(Box::new(lock_node));
                }
            }
        }
    }

    // 5. Sort nodes
    if !config.sort_bases.is_empty() {
        nodes.sort_by(|a, b| compare_nodes(a, b, &config.sort_bases));
    }
}

fn compare_nodes(a: &Node, b: &Node, sort_bases: &[String]) -> Ordering {
    for base in sort_bases {
        let (field, reverse) = if base.ends_with('_') {
            (&base[..base.len() - 1], true)
        } else {
            (base.as_str(), false)
        };

        let cmp = match field {
            "dev" => a.dev.cmp(&b.dev),
            "ino" | "inode" => a.ino.cmp(&b.ino),
            "nlink" | "nlinks" => a.nlink.cmp(&b.nlink),
            "typ" => a.node_type.code().cmp(&b.node_type.code()),
            "cat" => a.node_type.cat_rank().cmp(&b.node_type.cat_rank()),
            "user" => a.user_name.cmp(&b.user_name),
            "uid" => a.uid.cmp(&b.uid),
            "group" => a.group_name.cmp(&b.group_name),
            "gid" => a.gid.cmp(&b.gid),
            "size" => a.size.cmp(&b.size),
            "blocks" => a.blocks.cmp(&b.blocks),
            "btime" => a.btime.cmp(&b.btime),
            "ctime" => a.ctime.cmp(&b.ctime),
            "mtime" => a.mtime.cmp(&b.mtime),
            "atime" => a.atime.cmp(&b.atime),
            "name" => a.name.cmp(&b.name),
            "cname" => {
                let ca = a.name.trim_start_matches('.').to_lowercase();
                let cb = b.name.trim_start_matches('.').to_lowercase();
                ca.cmp(&cb)
            }
            "ext" => {
                let ea = a.name.rfind('.').map(|i| &a.name[i + 1..]).unwrap_or("");
                let eb = b.name.rfind('.').map(|i| &b.name[i + 1..]).unwrap_or("");
                ea.to_lowercase().cmp(&eb.to_lowercase())
            }
            _ => Ordering::Equal,
        };

        if cmp != Ordering::Equal {
            return if reverse { cmp.reverse() } else { cmp };
        }
    }
    Ordering::Equal
}

fn render_node_name(node: &Node, config: &Config, is_subordinate: bool) -> (String, usize) {
    let mut parts = String::new();
    let mut display_len = 0;

    let is_hidden = node.name.starts_with('.');

    if is_subordinate {
        parts.push_str("   └─ ");
        display_len += 6;
    }

    if config.icon {
        if let Some(ic) = node.icon {
            parts.push(ic);
            parts.push(' ');
            display_len += 2; // icon + 1 space

            if config.align && !is_hidden && !is_subordinate {
                parts.push(' ');
                display_len += 1;
            }
        } else {
            if config.align {
                if !is_hidden && !is_subordinate {
                    parts.push_str("   ");
                    display_len += 3;
                } else if !is_subordinate {
                    parts.push_str("  ");
                    display_len += 2;
                }
            } else {
                parts.push_str("  ");
                display_len += 2;
            }
        }
    } else {
        if config.align {
            if !is_hidden && !is_subordinate {
                parts.push(' ');
                display_len += 1;
            }
        }
    }

    // Styling based on importance difference: diff = node.importance - config.imp
    let diff = node.importance - config.imp;
    let (style_start, style_end) = if stdout_is_tty() {
        match diff {
            0 => ("\x1b[2m", "\x1b[0m"),
            1 => ("", ""),
            2 => ("\x1b[3m", "\x1b[0m"),
            d if d >= 3 => ("\x1b[4m", "\x1b[0m"),
            _ => ("", ""),
        }
    } else {
        ("", "")
    };

    parts.push_str(style_start);
    parts.push_str(&node.name);
    parts.push_str(style_end);
    display_len += node.name.chars().count();

    if config.suffix {
        let suf = node.node_type.suffix();
        parts.push_str(suf);
        display_len += suf.chars().count();
    }

    if config.sym && node.node_type == NodeType::Symlink {
        if let Some(ref target) = node.target {
            parts.push_str(" \u{f0054} ");
            parts.push_str(target);
            display_len += 3 + target.chars().count();
        }
    }

    (parts, display_len)
}

fn render_nodes(nodes: &[Node], config: &Config) {
    if !config.details.is_empty() {
        render_table_view(nodes, config);
    } else if config.grid && stdout_is_tty() {
        render_grid_view(nodes, config);
    } else {
        render_plain_view(nodes, config);
    }
}

fn render_plain_view(nodes: &[Node], config: &Config) {
    for node in nodes {
        let (rendered, _) = render_node_name(node, config, false);
        println!("{}", rendered);
        if let Some(ref sub) = node.subordinate {
            let (sub_rendered, _) = render_node_name(sub, config, true);
            println!("{}", sub_rendered);
        }
    }
}

fn render_grid_view(nodes: &[Node], config: &Config) {
    let term_width = get_terminal_width();

    let mut rendered_items = Vec::new();
    for node in nodes {
        rendered_items.push(render_node_name(node, config, false));
        if let Some(ref sub) = node.subordinate {
            rendered_items.push(render_node_name(sub, config, true));
        }
    }

    if rendered_items.is_empty() {
        return;
    }

    let max_item_len = rendered_items.iter().map(|(_, len)| *len).max().unwrap_or(0);
    let gap = 2;
    let col_width = max_item_len + gap;

    let num_cols = if term_width >= max_item_len {
        let c = (term_width + gap) / col_width;
        if c == 0 { 1 } else { c }
    } else {
        1
    };

    let total = rendered_items.len();
    if num_cols <= 1 {
        for (item_str, _) in rendered_items {
            println!("{}", item_str);
        }
        return;
    }

    let num_rows = (total + num_cols - 1) / num_cols;

    if config.down { // column-first
        for r in 0..num_rows {
            let mut line = String::new();
            for c in 0..num_cols {
                let idx = c * num_rows + r;
                if idx < total {
                    let (ref item_str, len) = rendered_items[idx];
                    line.push_str(item_str);
                    if c + 1 < num_cols && (idx + num_rows) < total {
                        let pad = col_width - len;
                        for _ in 0..pad {
                            line.push(' ');
                        }
                    }
                }
            }
            println!("{}", line);
        }
    } else { // row-first
        for r in 0..num_rows {
            let mut line = String::new();
            for c in 0..num_cols {
                let idx = r * num_cols + c;
                if idx < total {
                    let (ref item_str, len) = rendered_items[idx];
                    line.push_str(item_str);
                    if c + 1 < num_cols && (idx + 1) < total {
                        let pad = col_width - len;
                        for _ in 0..pad {
                            line.push(' ');
                        }
                    }
                }
            }
            println!("{}", line);
        }
    }
}

fn render_table_view(nodes: &[Node], config: &Config) {
    let mut all_flat_nodes = Vec::new();
    for node in nodes {
        all_flat_nodes.push((node, false));
        if let Some(ref sub) = node.subordinate {
            all_flat_nodes.push((sub.as_ref(), true));
        }
    }

    // Column headers and values
    struct ColumnSpec {
        id: String,
        header: String,
        is_right: bool,
    }

    let mut col_specs = Vec::new();
    for det in &config.details {
        match det.as_str() {
            "dev" => col_specs.push(ColumnSpec { id: "dev".into(), header: "Device".into(), is_right: true }),
            "ino" => col_specs.push(ColumnSpec { id: "ino".into(), header: "inode".into(), is_right: true }),
            "nlink" => col_specs.push(ColumnSpec { id: "nlink".into(), header: "Link#".into(), is_right: true }),
            "typ" => col_specs.push(ColumnSpec { id: "typ".into(), header: "T".into(), is_right: false }),
            "perm" => col_specs.push(ColumnSpec { id: "perm".into(), header: "Permissions".into(), is_right: false }),
            "oct" => col_specs.push(ColumnSpec { id: "oct".into(), header: "SUGO".into(), is_right: true }),
            "user" => col_specs.push(ColumnSpec { id: "user".into(), header: "User".into(), is_right: false }),
            "uid" => col_specs.push(ColumnSpec { id: "uid".into(), header: "UID".into(), is_right: true }),
            "group" => col_specs.push(ColumnSpec { id: "group".into(), header: "Group".into(), is_right: false }),
            "gid" => col_specs.push(ColumnSpec { id: "gid".into(), header: "GID".into(), is_right: true }),
            "size" => col_specs.push(ColumnSpec { id: "size".into(), header: "Size".into(), is_right: true }),
            "blocks" => col_specs.push(ColumnSpec { id: "blocks".into(), header: "Blocks".into(), is_right: true }),
            "btime" => col_specs.push(ColumnSpec { id: "btime".into(), header: "Created".into(), is_right: false }),
            "ctime" => col_specs.push(ColumnSpec { id: "ctime".into(), header: "Changed".into(), is_right: false }),
            "mtime" => col_specs.push(ColumnSpec { id: "mtime".into(), header: "Modified".into(), is_right: false }),
            "atime" => col_specs.push(ColumnSpec { id: "atime".into(), header: "Accessed".into(), is_right: false }),
            "git" => col_specs.push(ColumnSpec { id: "git".into(), header: "Git".into(), is_right: false }),
            _ => {}
        }
    }
    // Always append Name column
    col_specs.push(ColumnSpec { id: "name".into(), header: "Name".into(), is_right: false });

    // Format raw values for each row and column
    let mut table_rows: Vec<Vec<(String, usize)>> = Vec::new(); // (formatted_str, display_len)

    for (node, is_sub) in &all_flat_nodes {
        let mut row = Vec::new();
        for spec in &col_specs {
            let cell = match spec.id.as_str() {
                "dev" => (node.dev.to_string(), node.dev.to_string().len()),
                "ino" => (node.ino.to_string(), node.ino.to_string().len()),
                "nlink" => (node.nlink.to_string(), node.nlink.to_string().len()),
                "typ" => (node.node_type.code().to_string(), 1),
                "perm" => {
                    let s = format_mode(node.mode);
                    let l = s.len();
                    (s, l)
                }
                "oct" => {
                    let s = format_sugo(node.mode);
                    let l = s.len();
                    (s, l)
                }
                "user" => (node.user_name.clone(), node.user_name.len()),
                "uid" => (node.uid.to_string(), node.uid.to_string().len()),
                "group" => (node.group_name.clone(), node.group_name.len()),
                "gid" => (node.gid.to_string(), node.gid.to_string().len()),
                "size" => {
                    let s = format_size(node.size, &config.unit);
                    let l = s.len();
                    (s, l)
                }
                "blocks" => (node.blocks.to_string(), node.blocks.to_string().len()),
                "btime" => (format_time(node.btime), 20),
                "ctime" => (format_time(node.ctime), 20),
                "mtime" => (format_time(node.mtime), 20),
                "atime" => (format_time(node.atime), 20),
                "git" => ("   ".into(), 3),
                "name" => render_node_name(node, config, *is_sub),
                _ => ("".into(), 0),
            };
            row.push(cell);
        }
        table_rows.push(row);
    }

    // Compute column widths
    let mut col_widths = Vec::new();
    for (col_idx, spec) in col_specs.iter().enumerate() {
        let mut max_w = if config.header { spec.header.len() } else { 0 };
        for row in &table_rows {
            if row[col_idx].1 > max_w {
                max_w = row[col_idx].1;
            }
        }
        col_widths.push(max_w);
    }

    // Render header row if config.header
    if config.header {
        let mut header_line = String::new();
        for (col_idx, spec) in col_specs.iter().enumerate() {
            let width = col_widths[col_idx];
            let header_text = if spec.is_right {
                format!("{:>width$}", spec.header, width = width)
            } else {
                format!("{:<width$}", spec.header, width = width)
            };

            let styled_header = if stdout_is_tty() {
                format!("\x1b[1;4;3m{}\x1b[0m", header_text)
            } else {
                header_text
            };

            header_line.push_str(&styled_header);
            if col_idx + 1 < col_specs.len() {
                header_line.push(' ');
            }
        }
        println!("{}", header_line);
    }

    // Render data rows
    for row in table_rows {
        let mut row_line = String::new();
        for (col_idx, spec) in col_specs.iter().enumerate() {
            let width = col_widths[col_idx];
            let (ref cell_str, display_len) = row[col_idx];

            let pad = if width > display_len { width - display_len } else { 0 };
            if spec.is_right {
                for _ in 0..pad {
                    row_line.push(' ');
                }
                row_line.push_str(cell_str);
            } else {
                row_line.push_str(cell_str);
                if col_idx + 1 < col_specs.len() {
                    for _ in 0..pad {
                        row_line.push(' ');
                    }
                }
            }

            if col_idx + 1 < col_specs.len() {
                row_line.push(' ');
            }
        }
        println!("{}", row_line);
    }
}

fn process_path(path_str: &str, config: &Config, is_multi: bool, is_first: bool) {
    let path = Path::new(path_str);
    let sym_meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            if is_multi {
                println!("{}:\n\terror: {}", path_str, e);
            } else {
                println!("error: {}", e);
            }
            return;
        }
    };

    if sym_meta.file_type().is_dir() {
        let read_dir = match fs::read_dir(path) {
            Ok(rd) => rd,
            Err(e) => {
                if is_multi {
                    if !is_first { println!(); }
                    println!("{}:\nerror: {}", path_str, e);
                } else {
                    println!("error: {}", e);
                }
                return;
            }
        };

        if is_multi {
            if !is_first {
                println!();
            }
            println!("{}:", path_str);
        }

        let mut nodes = Vec::new();
        for entry_res in read_dir {
            if let Ok(entry) = entry_res {
                if let Ok(node) = build_node(&entry.path(), None) {
                    nodes.push(node);
                }
            }
        }

        filter_and_sort_nodes(&mut nodes, config);
        render_nodes(&nodes, config);
    } else {
        if let Ok(node) = build_node(path, Some(path_str.to_string())) {
            let mut nodes = vec![node];
            filter_and_sort_nodes(&mut nodes, config);
            render_nodes(&nodes, config);
        }
    }
}

fn main() {
    let config = parse_args();

    // Check input paths
    let mut top_files = Vec::new();
    let mut dir_paths = Vec::new();

    for path_str in &config.paths {
        let path = Path::new(path_str);
        if let Ok(m) = fs::symlink_metadata(path) {
            if m.file_type().is_dir() {
                dir_paths.push(path_str.clone());
            } else {
                top_files.push(path_str.clone());
            }
        } else {
            top_files.push(path_str.clone());
        }
    }

    let is_multi = config.paths.len() > 1;

    // Process top-level files first
    if !top_files.is_empty() {
        let mut file_nodes = Vec::new();
        for f in &top_files {
            let path = Path::new(f);
            if let Ok(node) = build_node(path, Some(f.clone())) {
                file_nodes.push(node);
            } else {
                println!("{}:\n\terror: No such file or directory (os error 2)", f);
            }
        }
        filter_and_sort_nodes(&mut file_nodes, &config);
        render_nodes(&file_nodes, &config);
    }

    // Process directories
    let mut is_first_dir = top_files.is_empty();
    for d in &dir_paths {
        process_path(d, &config, is_multi, is_first_dir);
        is_first_dir = false;
    }
}
