            };
            match SimpleRegex::new(&val) {
                Ok(r) => exclude = Some(r),
                Err(err_msg) => {
                    eprintln!("error: invalid value '{}' for '--exclude <EXCLUDE>': regex parse error:\n    {}\n    ^\nerror: {}\n\nFor more information, try '--help'.", val, val, err_msg);
                    process::exit(2);
                }
            }
        } else if arg == "-o" || arg.starts_with("-o=") || arg == "--only" || arg.starts_with("--only=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1.to_string()
            } else {
                idx += 1;
                if idx >= args.len() {
                    eprintln!("error: a value is required for '--only <ONLY>' but none was supplied\n\nFor more information, try '--help'.");
