// Backtracking Regex Engine
#[derive(Debug, Clone)]
enum RegexAST {
    Literal(char),
    Any,
    StartAnchor,
    EndAnchor,
    Class(Vec<(char, char)>, bool),
    Star(Box<RegexAST>),
    Plus(Box<RegexAST>),
    Question(Box<RegexAST>),
    Concat(Vec<RegexAST>),
    Alt(Vec<RegexAST>),
}

#[derive(Debug, Clone)]
struct SimpleRegex {
    ast: RegexAST,
}

impl SimpleRegex {
    fn new(pattern: &str) -> Result<Self, String> {
        let mut parser = RegexParser::new(pattern);
        let ast = parser.parse()?;
        Ok(SimpleRegex { ast })
    }

    fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        if self.has_start_anchor(&self.ast) {
            self.match_seq(&[self.ast.clone()], &chars, 0)
        } else {
            for i in 0..=chars.len() {
                if self.match_seq(&[self.ast.clone()], &chars, i) {
                    return true;
                }
            }
            false
        }
    }

    fn has_start_anchor(&self, ast: &RegexAST) -> bool {
        match ast {
            RegexAST::StartAnchor => true,
            RegexAST::Concat(vec) => vec.first().map_or(false, |a| self.has_start_anchor(a)),
            _ => false,
        }
    }

    fn match_single(&self, ast: &RegexAST, text: &[char], idx: usize) -> Option<usize> {
        match ast {
            RegexAST::Literal(c) => {
                if idx < text.len() && text[idx] == *c { Some(1) } else { None }
            }
            RegexAST::Any => {
                if idx < text.len() { Some(1) } else { None }
            }
            RegexAST::Class(ranges, inverted) => {
                if idx >= text.len() { return None; }
                let ch = text[idx];
                let mut matched = false;
                for &(start, end) in ranges {
                    if ch >= start && ch <= end {
                        matched = true;
                        break;
                    }
                }
                if *inverted { matched = !matched; }
                if matched { Some(1) } else { None }
            }
            _ => None,
        }
    }

    fn match_seq(&self, asts: &[RegexAST], text: &[char], idx: usize) -> bool {
        if asts.is_empty() {
            return true;
        }
        let head = &asts[0];
        let tail = &asts[1..];
        match head {
            RegexAST::StartAnchor => {
                if idx == 0 { self.match_seq(tail, text, idx) } else { false }
            }
            RegexAST::EndAnchor => {
                if idx == text.len() { self.match_seq(tail, text, idx) } else { false }
            }
            RegexAST::Literal(c) => {
                if idx < text.len() && text[idx] == *c {
                    self.match_seq(tail, text, idx + 1)
                } else {
                    false
                }
            }
            RegexAST::Any => {
                if idx < text.len() {
                    self.match_seq(tail, text, idx + 1)
                } else {
                    false
                }
            }
            RegexAST::Class(ranges, inverted) => {
                if idx >= text.len() { return false; }
                let ch = text[idx];
                let mut matched = false;
                for &(start, end) in ranges {
                    if ch >= start && ch <= end {
                        matched = true;
                        break;
                    }
                }
                if *inverted { matched = !matched; }
                if matched {
                    self.match_seq(tail, text, idx + 1)
                } else {
                    false
                }
            }
            RegexAST::Alt(alts) => {
                for alt in alts {
                    let mut new_seq = vec![alt.clone()];
                    new_seq.extend_from_slice(tail);
                    if self.match_seq(&new_seq, text, idx) {
                        return true;
                    }
                }
                false
            }
            RegexAST::Concat(vec) => {
                let mut new_seq = vec.clone();
                new_seq.extend_from_slice(tail);
                self.match_seq(&new_seq, text, idx)
            }
            RegexAST::Star(sub) => {
                // Greedy matching: try 1 match first, then 0 matches
                if let Some(consumed) = self.match_single(sub, text, idx) {
                    if consumed > 0 {
                        let mut new_seq = vec![RegexAST::Star(sub.clone())];
                        new_seq.extend_from_slice(tail);
                        if self.match_seq(&new_seq, text, idx + consumed) {
                            return true;
                        }
                    }
                }
                self.match_seq(tail, text, idx)
            }
            RegexAST::Plus(sub) => {
                let mut new_seq = vec![*sub.clone(), RegexAST::Star(sub.clone())];
                new_seq.extend_from_slice(tail);
                self.match_seq(&new_seq, text, idx)
            }
            RegexAST::Question(sub) => {
                let mut new_seq = vec![*sub.clone()];
                new_seq.extend_from_slice(tail);
                if self.match_seq(&new_seq, text, idx) {
                    return true;
                }
                self.match_seq(tail, text, idx)
            }
        }
    }
}

struct RegexParser {
    chars: Vec<char>,
    pos: usize,
}

impl RegexParser {
    fn new(raw: &str) -> Self {
        RegexParser {
            chars: raw.chars().collect(),
            pos: 0,
        }
    }

    fn parse(&mut self) -> Result<RegexAST, String> {
        let ast = self.parse_alt()?;
        if self.pos < self.chars.len() {
            return Err(format!("unexpected character at pos {}", self.pos));
        }
        Ok(ast)
    }

    fn parse_alt(&mut self) -> Result<RegexAST, String> {
        let mut alts = vec![self.parse_concat()?];
        while self.pos < self.chars.len() && self.chars[self.pos] == '|' {
            self.pos += 1;
            alts.push(self.parse_concat()?);
        }
        if alts.len() == 1 {
            Ok(alts.remove(0))
        } else {
            Ok(RegexAST::Alt(alts))
        }
    }

    fn parse_concat(&mut self) -> Result<RegexAST, String> {
        let mut vec = Vec::new();
        while self.pos < self.chars.len() {
            let ch = self.chars[self.pos];
            if ch == '|' || ch == ')' {
                break;
            }
            vec.push(self.parse_quantifier()?);
        }
        if vec.len() == 1 {
            Ok(vec.remove(0))
        } else {
            Ok(RegexAST::Concat(vec))
        }
    }

    fn parse_quantifier(&mut self) -> Result<RegexAST, String> {
        let atom = self.parse_atom()?;
        if self.pos < self.chars.len() {
            match self.chars[self.pos] {
                '*' => { self.pos += 1; Ok(RegexAST::Star(Box::new(atom))) }
                '+' => { self.pos += 1; Ok(RegexAST::Plus(Box::new(atom))) }
                '?' => { self.pos += 1; Ok(RegexAST::Question(Box::new(atom))) }
                _ => Ok(atom)
            }
        } else {
            Ok(atom)
        }
    }

    fn parse_atom(&mut self) -> Result<RegexAST, String> {
        if self.pos >= self.chars.len() {
            return Err("unexpected end of pattern".to_string());
        }
        let ch = self.chars[self.pos];
        self.pos += 1;
        match ch {
            '^' => Ok(RegexAST::StartAnchor),
            '$' => Ok(RegexAST::EndAnchor),
            '.' => Ok(RegexAST::Any),
            '\\' => {
                if self.pos >= self.chars.len() {
                    return Err("trailing backslash".to_string());
                }
                let escaped = self.chars[self.pos];
                self.pos += 1;
                match escaped {
                    'd' => Ok(RegexAST::Class(vec![('0', '9')], false)),
                    'w' => Ok(RegexAST::Class(vec![('a', 'z'), ('A', 'Z'), ('0', '9'), ('_', '_')], false)),
                    's' => Ok(RegexAST::Class(vec![(' ', ' '), ('\t', '\t'), ('\n', '\n'), ('\r', '\r')], false)),
                    other => Ok(RegexAST::Literal(other)),
                }
            }
            '[' => {
                let inverted = if self.pos < self.chars.len() && self.chars[self.pos] == '^' {
                    self.pos += 1;
                    true
                } else {
                    false
                };
                let mut ranges = Vec::new();
                let mut closed = false;
                while self.pos < self.chars.len() {
                    let c = self.chars[self.pos];
                    self.pos += 1;
                    if c == ']' {
                        closed = true;
                        break;
                    }
                    if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '-' && self.chars[self.pos + 1] != ']' {
                        self.pos += 1;
                        let end_c = self.chars[self.pos];
                        self.pos += 1;
                        ranges.push((c, end_c));
                    } else {
                        ranges.push((c, c));
                    }
                }
                if !closed {
                    return Err("unclosed character class".to_string());
                }
                Ok(RegexAST::Class(ranges, inverted))
            }
            '(' => {
                let ast = self.parse_alt()?;
                if self.pos < self.chars.len() && self.chars[self.pos] == ')' {
                    self.pos += 1;
                    Ok(ast)
                } else {
                    Err("unclosed parenthesis".to_string())
                }
            }
            '*' | '+' | '?' => Err(format!("unexpected quantifier '{}'", ch)),
            other => Ok(RegexAST::Literal(other)),
        }
    }
}

// Data structures
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum NodeType {
    Directory,
    Fifo,
    File,
    Socket,
    Symlink,
    CharDevice,
    BlockDevice,
}

impl NodeType {
    fn code(&self) -> char {
        match self {
            NodeType::Directory => 'd',
            NodeType::Fifo => 'p',
            NodeType::File => 'f',
            NodeType::Socket => 's',
            NodeType::Symlink => 'l',
            NodeType::CharDevice => 'c',
            NodeType::BlockDevice => 'b',
        }
    }

    fn cat_rank(&self) -> usize {
        match self {
            NodeType::Directory => 1,
            NodeType::Fifo => 2,
            NodeType::File => 3,
            NodeType::Socket => 4,
            NodeType::Symlink => 5,
            NodeType::CharDevice => 6,
            NodeType::BlockDevice => 7,
        }
    }

    fn suffix(&self) -> &'static str {
        match self {
            NodeType::Directory => "/",
            NodeType::Fifo => "|",
            NodeType::Socket => "=",
            NodeType::Symlink => "@",
            _ => "",
        }
    }

    fn match_filter(&self, f: &str) -> bool {
        match f {
            "dir" => *self == NodeType::Directory,
            "symlink" => *self == NodeType::Symlink,
            "fifo" => *self == NodeType::Fifo,
            "socket" => *self == NodeType::Socket,
            "block-device" => *self == NodeType::BlockDevice,
            "char-device" => *self == NodeType::CharDevice,
            "file" => *self == NodeType::File,
            "all" => true,
            _ => false,
        }
    }
}

#[derive(Debug, Clone)]
struct Node {
    name: String,
    node_type: NodeType,
    dev: u64,
    ino: u64,
    nlink: u64,
    uid: u32,
    gid: u32,
    user_name: String,
    group_name: String,
    size: u64,
    blocks: u64,
    mode: u32,
    atime: i64,
    mtime: i64,
    ctime: i64,
    btime: i64,
    target: Option<String>,
    icon: Option<char>,
    importance: i32,
    subordinate: Option<Box<Node>>,
}

fn get_node_icon(name: &str, node_type: NodeType, is_subordinate: bool) -> Option<char> {
    if is_subordinate {
        return Some('\u{f0456}');
    }

    match name {
        "Cargo.toml" => return Some('\u{f487}'),
        "Cargo.lock" => return Some('\u{f0456}'),
        "Dockerfile" | "docker-compose.yml" => return Some('\u{f4b7}'),
        "LICENSE" | "LICENCE" | "COPYING" => return Some('\u{f495}'),
        "README" | "README.md" | "README.txt" | "README.rst" | "README.org" => return Some('\u{f02d}'),
        ".gitignore" | ".gitattributes" | ".gitmodules" => return Some('\u{f02a2}'),
        ".env" | ".env.local" => return Some('\u{e22f}'),
        "Makefile" => return Some('\u{f070e}'),
        _ => {}
    }

    if name.starts_with(".env.") {
        return Some('\u{e22f}');
    }

    if let Some(ext_idx) = name.rfind('.') {
        let ext = &name[ext_idx + 1..];
        match ext {
            "rs" => return Some('\u{e68b}'),
            "sh" | "bash" | "zsh" | "fish" => return Some('\u{f489}'),
            "json" | "toml" | "yaml" | "yml" => return Some('\u{e60b}'),
            "md" => return Some('\u{f48a}'),
            "txt" => return Some('\u{e612}'),
            "ini" | "conf" | "cfg" => return Some('\u{e615}'),
            "png" | "jpg" | "jpeg" | "gif" | "svg" | "ico" => return Some('\u{f02e9}'),
            "mp3" | "wav" | "flac" => return Some('\u{f04c3}'),
            "mp4" | "avi" | "mkv" | "mov" => return Some('\u{f0567}'),
            _ => {}
        }
    }

    match node_type {
        NodeType::Directory => Some('\u{f07b}'),
        NodeType::Symlink => Some('\u{f0339}'),
        NodeType::Fifo => Some('\u{f07e5}'),
        NodeType::Socket => Some('\u{f07e8}'),
        NodeType::CharDevice => Some('\u{f1dd}'),
        NodeType::BlockDevice => Some('\u{f07bd}'),
        NodeType::File => None,
    }
}

fn get_node_importance(name: &str) -> i32 {
    if name == "." {
        return 3;
    }
    if name.starts_with("README") || name.starts_with("README.") {
        return 3;
    }
    if name == ".DS_Store" {
        return -1;
    }
    if name.starts_with('.') {
        return 0;
    }
    1
}

fn build_node(path: &Path, display_name: Option<String>) -> Result<Node, String> {
    let sym_meta = fs::symlink_metadata(path).map_err(|e| format!("{}", e))?;
    let file_type = sym_meta.file_type();

    let node_type = if file_type.is_dir() {
        NodeType::Directory
    } else if file_type.is_symlink() {
        NodeType::Symlink
    } else if file_type.is_fifo() {
        NodeType::Fifo
    } else if file_type.is_socket() {
        NodeType::Socket
    } else if file_type.is_block_device() {
        NodeType::BlockDevice
    } else if file_type.is_char_device() {
        NodeType::CharDevice
    } else {
        NodeType::File
    };

    let target = if node_type == NodeType::Symlink {
        fs::read_link(path).ok().map(|p| p.to_string_lossy().into_owned())
    } else {
        None
    };

    let name = display_name.unwrap_or_else(|| {
        path.file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_else(|| path.to_string_lossy().into_owned())
    });

    let uid = sym_meta.uid();
    let gid = sym_meta.gid();
    let user_name = get_username(uid);
    let group_name = get_groupname(gid);

    let atime = sym_meta.atime();
    let mtime = sym_meta.mtime();
    let ctime = sym_meta.ctime();
    let btime = ctime;

    let icon = get_node_icon(&name, node_type, false);
    let importance = get_node_importance(&name);

    Ok(Node {
        name,
        node_type,
        dev: sym_meta.dev(),
        ino: sym_meta.ino(),
        nlink: sym_meta.nlink(),
        uid,
        gid,
        user_name,
        group_name,
        size: sym_meta.size(),
        blocks: sym_meta.blocks(),
        mode: sym_meta.mode(),
        atime,
        mtime,
        ctime,
        btime,
        target,
        icon,
        importance,
        subordinate: None,
    })
}

fn format_time(time_secs: i64) -> String {
    let days = if time_secs >= 0 { time_secs / 86400 } else { (time_secs - 86399) / 86400 };
    let mut rem_secs = time_secs % 86400;
    if rem_secs < 0 { rem_secs += 86400; }

    let hours = rem_secs / 3600;
    let mins = (rem_secs % 3600) / 60;

    let z = days + 719468;
    let era = (if z >= 0 { z } else { z - 146096 }) / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = (yoe as i64) + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = (mp as i64) + (if mp < 10 { 3 } else { -9 });
    let year = y + (if m <= 2 { 1 } else { 0 });

    let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    let month_str = months[(m - 1) as usize];

    let (h12, ampm) = if hours == 0 {
        (12, "am")
    } else if hours < 12 {
        (hours, "am")
    } else if hours == 12 {
        (12, "pm")
    } else {
        (hours - 12, "pm")
    };

    format!("{:04}-{}-{:02} {:02}:{:02}{}", year, month_str, d, h12, mins, ampm)
}

fn format_mode(mode: u32) -> String {
    let u_r = if mode & 0o400 != 0 { 'r' } else { '-' };
    let u_w = if mode & 0o200 != 0 { 'w' } else { '-' };
    let u_x = match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };

    let g_r = if mode & 0o040 != 0 { 'r' } else { '-' };
    let g_w = if mode & 0o020 != 0 { 'w' } else { '-' };
    let g_x = match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };

    let o_r = if mode & 0o004 != 0 { 'r' } else { '-' };
    let o_w = if mode & 0o002 != 0 { 'w' } else { '-' };
    let o_x = match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        (false, false) => '-',
    };

    format!("{}{}{} {}{}{} {}{}{}", u_r, u_w, u_x, g_r, g_w, g_x, o_r, o_w, o_x)
}

fn format_sugo(mode: u32) -> String {
    let sugo = mode & 0o7777;
    if sugo > 0o0777 {
        format!("{:04o}", sugo)
    } else {
        format!(" {:03o}", sugo)
    }
}

fn format_size(size: u64, unit: &str) -> String {
    match unit {
        "decimal" => {
            let units = ["B", "kB", "MB", "GB", "TB", "PB", "EB"];
            let mut s = size as f64;
            let mut u_idx = 0;
            while s >= 1000.0 && u_idx < units.len() - 1 {
                s /= 1000.0;
                u_idx += 1;
            }
            let u = units[u_idx];
            if u == "B" {
                format!("{:>5.1}  B", s)
            } else {
                format!("{:>5.1} {}", s, u)
            }
        }
        "none" => {
            format!("{} B", size)
        }
        _ => { // binary
            let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
            let mut s = size as f64;
            let mut u_idx = 0;
            while s >= 1024.0 && u_idx < units.len() - 1 {
                s /= 1024.0;
                u_idx += 1;
            }
            let u = units[u_idx];
            if u == "B" {
                format!("{:>6.1}   B", s)
            } else {
                format!("{:>6.1} {}", s, u)
            }
        }
    }
}

