            };
            match parse_bool(val, "--down <DOWN>") {
                Ok(b) => down = b,
                Err(e) => { eprintln!("{}", e); process::exit(2); }
            }
        } else if arg == "-i" || arg.starts_with("-i=") || arg == "--icon" || arg.starts_with("--icon=") {
            let val = if arg.contains('=') {
                arg.split_once('=').unwrap().1
